import sys
data = sys.stdin.read().split()
if data:
    n = int(data[0])
    tokens = data[1:1+n]
    if not tokens: print('true'); sys.exit(0)
    class Node:
        def __init__(self, v): self.v = int(v); self.left = None; self.right = None
    from collections import deque
    root = Node(tokens[0])
    q = deque([root])
    idx = 1
    while q and idx < len(tokens):
        curr = q.popleft()
        if idx < len(tokens) and tokens[idx] != 'null':
            curr.left = Node(tokens[idx]); q.append(curr.left)
        idx += 1
        if idx < len(tokens) and tokens[idx] != 'null':
            curr.right = Node(tokens[idx]); q.append(curr.right)
        idx += 1
    def is_valid(node, low, high):
        if not node: return True
        if not (low < node.v < high): return False
        return is_valid(node.left, low, node.v) and is_valid(node.right, node.v, high)
    print('true' if is_valid(root, float('-inf'), float('inf')) else 'false')
